// Temporary branch-only runner. Applies hash-pinned, locally syntax/unit-checked edits.
// No production credentials or inference. Removed before the implementation commit.
import {execFileSync,spawnSync} from 'node:child_process';
import {appendFileSync,readFileSync,writeFileSync,unlinkSync} from 'node:fs';
const encoded='';
const apply=String.raw`import sys,gzip,json,hashlib,pathlib
raw=gzip.decompress(sys.stdin.buffer.read())
assert hashlib.sha256(raw).hexdigest()=='235913a41072c7d336e70258ef5da59f12b0004d0ff519613f4b0583420409f4','Payload integrity failed'
ops=json.loads(raw)
for op in ops:
 p=pathlib.Path(op['path']); old=p.read_text() if p.exists() else ''
 assert hashlib.sha256(old.encode()).hexdigest()==op['before'], 'Baseline changed: '+str(p)
 new=old
 for e in reversed(op['edits']):new=new[:e['start']]+e['text']+new[e['end']:]
 assert hashlib.sha256(new.encode()).hexdigest()==op['after'],'Target mismatch: '+str(p)
 p.write_text(new)
print('Applied '+str(len(ops))+' exact verified file edits')`;
execFileSync('python3',['-c',apply],{input:Buffer.from(encoded,'base64'),stdio:['pipe','inherit','inherit']});
const log='/tmp/image-viewer-verification.log';
function run(command,args=[],env={}){const result=spawnSync(command,args,{encoding:'utf8',env:{...process.env,...env},timeout:360000,maxBuffer:15*1024*1024});appendFileSync(log,'\n$ '+command+' '+args.join(' ')+'\n'+(result.stdout||'')+(result.stderr||''));console.log(command,args.join(' '),'exit',result.status);if(result.status!==0)throw Error('Verification failed; no source commit: '+command+' '+args.join(' ')+'\n'+(result.stderr||result.error||''));}
for(const path of ['lab/lab.js','lab/precision-edit.js','lab/image-viewer-editor.js'])run('node',['--check',path]);
run('git',['diff','--check']);
run('node',['--test','tests/lab-approved-image-ui-contract.test.mjs','tests/lab-precision-edit.test.mjs','tests/lab-image-replacement-intent.test.mjs','tests/lab-image-replacement-composite.test.mjs','tests/lab-image-replacement-backend.test.mjs','tests/lab-image-replacement-draft.test.mjs']);
run('npm',['install','--prefix','/tmp/pv-viewer-check','--no-save','playwright@1.57.0']);
run('node',['/tmp/pv-viewer-check/node_modules/playwright/cli.js','install','--with-deps','chromium']);
const env={PV_PLAYWRIGHT_MODULE:'/tmp/pv-viewer-check/node_modules/playwright/index.mjs'};
for(const path of ['tests/lab-precision-edit-ui.mjs','tests/lab-image-replacement-ui.mjs','tests/lab-image-replacement-flow-ui.mjs','tests/lab-image-prompt-paste-ui.mjs','tests/lab-first-image-instant-browser.mjs','tests/lab-studio-layout-ui.mjs'])run('node',[path],env);
run('node',['tests/lab-image-oneclick-ui.mjs'],{...env,PV_RETOUCH_NAV_ONLY:'1'});
console.log('All scoped checks passed. Source remains on this isolated branch for PR review.');
